from review import card,save,DATE
i='TCS-3690';_,c=card(i);refs=c['references'];refs[0]['locator']='Introduction, Remark 2 and conclusion: untuned adversarial tracking regret; distinguish the proved stochastic change-count theorem.'
refs += [dict(id='pareto',title='The Pareto Frontier of Model Selection for General Contextual Bandits',authors='Teodor Marinov; Julian Zimmert',year=2021,url='https://arxiv.org/abs/2110.13282',pdf_url='https://arxiv.org/pdf/2110.13282',locator='NeurIPS 2021; lower-bound consequence for switching regret against an adaptive adversary.'),dict(id='significant',title='Tracking Most Significant Arm Switches in Bandits',authors='Joseph Suk; Samory Kpotufe',year=2022,url='https://proceedings.mlr.press/v178/suk22a.html',pdf_url='https://proceedings.mlr.press/v178/suk22a/suk22a.pdf',locator='Introduction footnote 1, related work and conclusion explicitly separate adaptive switching regret against arbitrary comparator sequences from tracking the pointwise best arm.'),dict(id='static_dynamic',title='Achieving Optimal Static and Dynamic Regret Simultaneously in Bandits with Deterministic Losses',authors='Jian Qian; Chen-Yu Wei',year=2026,url='https://arxiv.org/abs/2602.07418v2',pdf_url='https://arxiv.org/pdf/2602.07418v2',locator='Preprint, revised 17 February 2026; Sections 1–3 define the known loss-vector change budget; Section 7 explicitly retains the original untuned switching-benchmark question.')]
notes=['Recovered the expected switching-regret rate and its simultaneous quantification over unknown comparator switch budgets.','Explicitly retained the surviving oblivious-adversary branch, because subsequent work rules out the general adaptive-adversary guarantee. This is a documented scope restriction, not an equivalence to all adversarial models.','Defined finite-arm scalar feedback, arbitrary fixed loss vectors, hindsight comparators, switch count and universal logarithmic factors.','Checked 2022 pointwise-best-arm tracking and the February 2026 known-change-budget preprint; neither proves the stated simultaneous guarantee.','Checked the March 2026 unconstrained linear-bandit result; its unrestricted vector actions do not supply an algorithm for finite-arm feedback.']
save(i,dict(title='Untuned switching regret for oblivious adversarial bandits',formal='Does there exist a randomized bandit algorithm A and universal constants C>0 and p≥0 such that the following holds? For every number of arms K≥2, horizon T≥1 and loss sequence ℓ₁,…,ℓ_T∈[0,1]ᴷ fixed before play, give A only K and T. Simultaneously for every integer S∈{0,…,T−1}, require R_S(A;ℓ)≤C√(K(S+1)T)[log(2KT)]ᵖ, where R_S is the expected loss of A minus the loss of the best hindsight arm sequence with at most S switches. The same algorithm, without S or a bound on S as input, must satisfy every one of these inequalities. This is the remaining oblivious-adversary case of the source question; the corresponding general adaptive-adversary target was subsequently ruled out.',definitions='At round t, A chooses an arm I_t∈[K]={1,…,K} using K, T, its random bits and the previously chosen arms and observed losses. It incurs and observes only the scalar ℓ_t(I_t). It does not see the other coordinates of ℓ_t or receive any announcement when losses or comparator arms change. The entire sequence of loss vectors is chosen independently of the learner’s realized random bits before the first round; arbitrary variation from round to round is allowed. For an arm sequence j=(j₁,…,j_T)∈[K]ᵀ put s(j)=|{t∈{2,…,T}:j_t≠j_{t−1}}|. Define R_S(A;ℓ)=E_A[Σ_{t=1}^T ℓ_t(I_t)]−min_{j:s(j)≤S}Σ_{t=1}^Tℓ_t(j_t). The expectation is only over A’s randomness. Comparators may be chosen with full knowledge of the loss sequence and are not required to select a pointwise best arm. S counts switches, so S+1 counts the maximum number of constant-arm segments and S=0 recovers static regret. The logarithm is natural; C and p are independent of K,T,S and ℓ. This specifies the meaning of the target bound up to logarithmic factors. Since R_S≤T automatically, the bound is informative only where its right side is smaller than T. Simultaneous means all these expected-regret guarantees hold for one A; it does not demand a simultaneous high-probability event. The question imposes no separate running-time or memory bound. An adaptive adversary, which may set future loss vectors in response to realized past actions, is a different model excluded from this remaining question.',question_type='yes_no',answer_criterion='Give one algorithm with a proof of the displayed uniform expected-regret bounds for all finite K,T, fixed loss sequences and switch budgets, or prove that no such algorithm and universal constants exist. Tuning the algorithm to S, bounding only regret to the pointwise best arm by its number of changes, or establishing a lower bound that needs an adaptive adversary is insufficient for this oblivious switching-comparator question.',context_blocks=[dict(title='Knowing the budget gives the target rate',text='The source explains that appropriately tuned EXP3.S attains the minimax switching-regret order up to logarithmic factors. Its own untuned theorem counts changes in stochastic reward distributions; it leaves adversarial tracking as a separate question.',citation='primary'),dict(title='Adaptivity of the adversary changes the answer',text='The 2021 lower bound rules out the analogous simultaneous objective for adaptive adversaries. The present card explicitly narrows the historical question to the oblivious case retained in later work.',citation='pareto'),dict(title='Pointwise-best-arm tracking is different',text='The 2022 result adapts to severe changes in the pointwise best arm. Its introduction and conclusion explicitly leave open regret against arbitrary switching comparator sequences. A slowly switching hindsight comparator can matter even when the pointwise best arm changes frequently.',citation='significant'),dict(title='Recent progress still uses a supplied change budget',text='The February 2026 preprint obtains simultaneous optimal static and dynamic regret for deterministic losses when the number of changes in the loss vector is known. Its conclusion still asks for optimal guarantees across all switching benchmarks. That supplied budget and restricted loss-sequence structure are absent from this card.',citation='static_dynamic')],why='Would determine whether finite-arm exploration can adapt to every comparator’s rate of change without prior tuning, unifying optimal static and tracking guarantees for arbitrary fixed loss sequences.',references=refs,progress=[dict(date='2019',text='Optimal adaptation to an unknown stochastic distribution-change count is established; the source leaves untuned adversarial tracking open.',citation='primary'),dict(date='2021',text='A lower bound eliminates the general adaptive-adversary version.',citation='pareto'),dict(date='2022',text='Pointwise-best-arm tracking improves, while the authors explicitly retain the broader switching-comparator question.',citation='significant'),dict(date='2026-02-17',text='A revised preprint gives simultaneous static/dynamic guarantees for deterministic losses with a known loss-change budget; its conclusion retains the untuned question.',citation='static_dynamic')],status='open',status_note='Read the source question and later papers distinguishing stochastic distribution changes, pointwise best-arm switches and hindsight comparator switches. The February 2026 preprint explicitly retains the general untuned benchmark question. Also checked the March 2026 unconstrained linear-bandit preprint, whose action space differs. No resolution of the stated oblivious finite-arm target was found through 12 September 2026; this is not an exhaustive search or independent proof audit.',model_self_contained=True,requires_context=False,review_note='Self-contained formulation of the surviving oblivious branch, with universal polylogarithmic precision and an explicit record of the historical scope restriction.',importance=dict(score=c['importance']['score'],method='editorial',reason='Tests the fundamental cost of adapting exploration to unknown comparator complexity under finite-arm feedback. It remains a broad barrier beyond adaptation to stochastic changes. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['A finite-arm bandit learner observes only the loss of its selected arm.','Its comparator is the best hindsight arm sequence with at most S switches.','The remaining question asks for the optimal switching-regret rate for every S simultaneously without receiving S, when all loss vectors are fixed before play.','Adaptive adversaries admit an impossibility result, while pointwise-best-arm tracking solves a different objective.','A February 2026 preprint advances simultaneous static and dynamic regret with a known change budget and explicitly preserves the untuned question.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','pareto','significant','static_dynamic'])),notes=notes,checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2603.25916'])
